window.products.push({"id":494321,"name":"Laura Ashley Home - Queen Sheet Set, Plush Fleece Bedding, Warm & Cozy Home Decor, Brushed for Added Softness (Rachel, Queen)","category":"homeandappliances","retail price":29.07,"sale price":null,"image":"https://m.media-amazon.com/images/I/91q+KYiX2rL._AC_SL1500_.jpg","description":"Cozy up with Laura Ashley's new Signature Ultra Soft Plush Sheet Sets. Constructed with a two-sided fleece plush, this 100% polyester sheet set is super soft and features a brushed finish for that added soft comfort. Available in solids or a stylish printed pattern, you are sure to find the right set for your home decor. The included fitted sheet is fully elastic, which helps keep your sheet in place throughout your night's sleep. Sheet set is machine washable for easy care and comes packaged in a reusable self fabric bag for storage!","images":["https://m.media-amazon.com/images/I/91q+KYiX2rL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Laura Ashley","source_asin":"B09GW8PJRG","category_path":"Home & Kitchen"},"sku":"BM-494321","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B09GW8PJRG","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B09GW8PJRG","price_pending":true,"merchant_ready":false});
